import os

# Navigate the nested directory structure
def list_files_recursive(path, max_depth=3, current_depth=0):
    if current_depth > max_depth:
        return
    try:
        items = os.listdir(path)
    except:
        return
    for item in sorted(items):
        full = os.path.join(path, item)
        if os.path.isfile(full):
            size = os.path.getsize(full)
            print(f"{'  '*current_depth}F {item} ({size}b)")
        else:
            print(f"{'  '*current_depth}D {item}/")
            list_files_recursive(full, max_depth, current_depth+1)

